-- Run as postgres after migration 20261105000100. All test records roll back.
begin;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end$$;
create function pg_temp.denied(statement text) returns void language plpgsql as $$begin begin execute statement;exception when others then return;end;raise exception 'FAIL: unexpectedly allowed %',statement;end$$;
create function pg_temp.act(c jsonb,rev integer default null,r uuid default gen_random_uuid()) returns void language sql as $$select public.demo_command(c,r,rev);$$;
insert into auth.users(id,raw_user_meta_data) values('50000000-0000-0000-0000-000000000001','{"display_name":"Demo test owner"}'),('50000000-0000-0000-0000-000000000002','{"display_name":"Demo test borrower"}'),('50000000-0000-0000-0000-000000000003','{"display_name":"Demo test outsider"}');
insert into public.demo_profiles select id,jsonb_build_object('name','Demo tester','username','test_'||right(id::text,4),'bio','','location','Clementi','colour','#808080'),1 from auth.users where id::text like '50000000-%';
set local role authenticated;
select set_config('request.jwt.claim.sub','50000000-0000-0000-0000-000000000001',true);
